@extends('layouts.app') @section('title','Вахта общежития') @section('content')<a href="{{route('dormitory.index')}}">← Общежитие</a><h1 class="h4">📷 Вахта — сканирование пропуска</h1><div class="d-flex gap-2 mb-2"><select id="dir" class="form-select"><option value="in">Вход</option><option value="out">Выход</option></select><button id="start" class="btn btn-primary">Камера</button></div><video id="v" playsinline style="width:100%;max-width:600px;background:#111"></video><form id="manual" class="d-flex gap-2 mt-2"><input id="token" class="form-control" placeholder="Токен / данные сканера"><button class="btn btn-outline-primary">Проверить</button></form><div id="result" class="alert mt-3 d-none"></div><script>async function send(t){let r=await fetch('{{route('dormitory.gate.scan')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'},body:JSON.stringify({token:t,direction:document.getElementById('dir').value})});let j=await r.json();let e=document.getElementById('result');e.className='alert mt-3 '+(j.ok?'alert-success':'alert-danger');e.textContent=j.ok?j.student+' · '+j.building+', комната '+j.room:(j.message||'Ошибка');}document.getElementById('manual').onsubmit=e=>{e.preventDefault();send(document.getElementById('token').value.trim())};document.getElementById('start').onclick=async()=>{if(!('BarcodeDetector'in window)){alert('Браузер не поддерживает BarcodeDetector. Используйте USB/Bluetooth-сканер или ручной ввод.');return}let s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});v.srcObject=s;await v.play();let d=new BarcodeDetector({formats:['qr_code']});let busy=false;setInterval(async()=>{if(busy)return;busy=true;try{let a=await d.detect(v);if(a.length)await send(a[0].rawValue)}catch(e){}busy=false},900)};</script>@endsection